BEGIN;
WITH p AS (SELECT value AS r FROM jsonb_array_elements($ap$[{"id": "c25a1672-9e83-4eca-87a7-1240526a07fb", "term": "Energy-Time Curve", "definition": "An Energy-Time Curve (ETC) is a plot of received sound energy (level) versus time at a measurement position, computed from the room impulse response, classically via the Hilbert transform to obtain the analytic-signal envelope. It displays the arrival of the direct sound and each subsequent reflection in the time domain, letting an analyst identify their delay and relative level. The method was developed by Richard Heyser in connection with Time Delay Spectrometry.", "plain_english": "An Energy-Time Curve shows sound energy arriving at a point over time. The tall first spike is the direct sound. Later spikes are echoes bouncing off surfaces. The time gaps tell you how far away those surfaces are. Engineers use the curve to find and tame strong reflections.", "purpose_function": "It shows exactly when and how strongly reflections arrive, so engineers can locate problem surfaces and set delay times; it exists to make reflections visible in the time domain.", "practical_application": "A technician captures an impulse response and reads its energy-time curve to spot a strong late reflection off a back wall, then treats that surface or adjusts speaker aim and delay.", "category": "Acoustic Measurement", "difficulty": "intermediate", "achievement_id": "ea5ea932-9963-43ee-a637-163e258e53d0", "cross": [], "related_terms": ["Impulse Response", "Reflection", "Early Decay Time", "Comb Filtering", "Reverberation Time"], "common_mistakes": ["Confusing the energy-time curve with a frequency response, which shows level versus frequency rather than time", "Misreading the time axis and so mislocating the reflecting surface", "Ignoring that the measurement setup and windowing affect which reflections appear", "Assuming every later spike is a real room reflection rather than a measurement artifact"], "scenario_contexts": ["Locating a slap-echo surface in a control room", "Setting loudspeaker delay times by reading reflection arrival times", "Verifying that acoustic treatment reduced a strong reflection", "Troubleshooting comb filtering traced to a specific early reflection"], "formula_symbolic": "", "formula_words": ""}, {"id": "6d5cf514-79b4-4c11-bea4-7c90378244d5", "term": "Flanking Transmission", "definition": "Flanking transmission is sound that travels between two spaces by indirect paths - through connected floors, ceilings, side walls, ductwork, or gaps and penetrations - rather than directly through the common separating partition. It lowers the real-world sound isolation between rooms below what the partition alone would provide, and it is addressed in building-acoustics standards such as ISO 10140 (laboratory) and ISO 16283 (field), with ASTM E336 covering field measurement in the United States.", "plain_english": "Flanking transmission is sound that sneaks between rooms the long way. Instead of going straight through the shared wall, it travels through side walls, floors, ceilings, ducts, or small gaps. This is why a supposedly soundproof wall can still leak noise. Sealing these side paths is key to real sound isolation.", "purpose_function": "It names the indirect leakage paths that limit sound isolation, so designers know that a good dividing wall alone is not enough and the surrounding structure must also be treated.", "practical_application": "A technician chasing noise between a studio and a neighboring room checks flanking paths, such as a shared ceiling plenum, a common floor, back-to-back outlets, and ducts, instead of only upgrading the dividing wall.", "category": "Sound Isolation", "difficulty": "intermediate", "achievement_id": "ea5ea932-9963-43ee-a637-163e258e53d0", "cross": [], "related_terms": ["Sound Transmission Class", "Transmission Loss", "Decoupling", "Structure-Borne Sound", "Airborne Sound"], "common_mistakes": ["Upgrading only the dividing wall and ignoring flanking paths, so overall isolation barely improves", "Confusing a laboratory STC rating with real field performance, which flanking degrades", "Overlooking small leaks such as unsealed penetrations, ducts, and back-to-back electrical boxes", "Assuming mass alone stops sound while ignoring structure-borne flanking through the building frame"], "scenario_contexts": ["Tracing noise leaking between two adjacent studios that share a ceiling", "Explaining why a new heavy wall did not stop bleed into the next room", "Sealing duct and conduit penetrations to improve isolation", "Field-testing sound isolation and finding flanking through the floor slab"], "formula_symbolic": "", "formula_words": ""}, {"id": "8e082b24-3b72-490b-b21f-317f7d259cbc", "term": "Acoustic Compliance", "definition": "The acoustic property describing how easily a volume of air (or an acoustic element) yields to an applied sound pressure; it is the acoustic analog of mechanical compliance and of electrical capacitance, and it stores potential energy. For a sealed enclosure of volume V it equals the volume divided by air density times the speed of sound squared, so a larger trapped volume is more compliant (a softer spring).", "plain_english": "Trapped air acts like a spring. When you push on it, it pushes back. Acoustic compliance measures how springy that air is. A bigger sealed air space is softer and easier to squeeze. This is why the air inside a speaker box behaves like a spring on the cone.", "purpose_function": "It models the springiness of trapped air so designers can predict how an enclosure stiffens a driver and where the system resonates. It exists to bring air's give into the electrical-style circuit models used for loudspeaker and room analysis.", "practical_application": "A loudspeaker designer uses a box's air compliance to set a sealed cabinet's low-frequency roll-off and system resonance, knowing a smaller box is stiffer and raises the tuning.", "category": "Electroacoustic Analogies", "difficulty": "intermediate", "achievement_id": "f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37", "cross": [], "related_terms": ["Acoustic Mass", "Acoustic Impedance", "Radiation Impedance", "Helmholtz Resonance", "Compliance", "Sealed Enclosure"], "common_mistakes": ["Confusing acoustic compliance (springiness, the analog of capacitance) with acoustic mass (inertia, the analog of inductance)", "Thinking a bigger sealed box is stiffer; a larger air volume is actually more compliant, a softer spring", "Assuming compliance dissipates energy like a resistor; it stores potential energy and does not dissipate it", "Mixing up the mechanical compliance of the cone suspension with the acoustic compliance of the air load"], "scenario_contexts": ["Sizing a sealed subwoofer box, where the air compliance combines with cone stiffness to set the system resonance", "Modeling the air volume of a room or bass trap as an acoustic spring in an analysis", "Designing a bass-reflex box where the box compliance resonates with the port's acoustic mass"], "formula_symbolic": "", "formula_words": ""}, {"id": "c436c7ab-fe69-4c35-8c4c-9ddf897c73f5", "term": "Acoustic Mass", "definition": "The acoustic property representing the inertia of a slug of air that moves back and forth as a unit, as in a port, duct, or small hole; it is the acoustic analog of mechanical mass and of electrical inductance, and it stores kinetic energy. For a tube it equals air density times the effective length divided by the cross-sectional area, where the effective length includes end corrections.", "plain_english": "Air has weight, so it resists being pushed suddenly. Acoustic mass measures that resistance in a tube or port. The air inside behaves like a heavy plug that takes effort to get moving. Longer, narrower openings hold more of this air mass. This is what makes a vented speaker port work.", "purpose_function": "It lets designers treat the air in ports and ducts as a moving mass in circuit-style models, so they can predict resonances. It exists because moving air stores kinetic energy and works against acoustic compliance to form tuned resonators.", "practical_application": "A designer sizes a bass-reflex port's length and area to set its acoustic mass, tuning the box's Helmholtz resonance to extend low-frequency output.", "category": "Electroacoustic Analogies", "difficulty": "intermediate", "achievement_id": "f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37", "cross": [], "related_terms": ["Acoustic Compliance", "Acoustic Impedance", "Radiation Impedance", "Helmholtz Resonance", "Port", "End Correction"], "common_mistakes": ["Confusing acoustic mass (inertia, the analog of inductance) with acoustic compliance (springiness, the analog of capacitance)", "Forgetting the end correction, so the port acts longer, and has more acoustic mass, than its physical length", "Thinking a wider port has more acoustic mass; a larger cross-sectional area actually lowers the acoustic mass", "Believing acoustic mass dissipates energy; it stores kinetic energy and does not dissipate it"], "scenario_contexts": ["Tuning a bass-reflex port so its air mass resonates with the box's air compliance", "Accounting for the co-vibrating air on a radiating diaphragm as an added acoustic mass", "Predicting a Helmholtz absorber's resonance from its neck air mass and cavity compliance"], "formula_symbolic": "", "formula_words": ""}, {"id": "cd4c7f3b-33d7-4a02-8878-9536feb8ec53", "term": "Acoustic Transformer", "definition": "An acoustic device, most commonly a horn, that transforms acoustic impedance between two regions, coupling the high acoustic impedance at a small-area diaphragm or throat to the low acoustic impedance of open air at a large-area mouth. By better matching these impedances it raises radiation efficiency, much as an electrical transformer's turns ratio steps impedance up or down.", "plain_english": "Air is hard for a small speaker cone to push efficiently. A horn helps by slowly widening from a small throat to a large mouth. This gradual flare lets the driver grip the air far better. It works like a gear or lever between the driver and the room. That is why horn speakers can be loud and efficient.", "purpose_function": "It matches the mismatched impedances of a small vibrating surface and the surrounding air, so more energy radiates instead of reflecting back into the driver. It exists to boost efficiency and output, especially for high-frequency compression drivers and long-throw systems.", "practical_application": "A live-sound engineer uses horn-loaded compression drivers on the tops so the high frequencies project efficiently across a large venue.", "category": "Acoustic Loading", "difficulty": "intermediate", "achievement_id": "f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37", "cross": [], "related_terms": ["Radiation Impedance", "Impedance Matching", "Acoustic Impedance", "Compression Driver", "Horn", "Acoustic Compliance"], "common_mistakes": ["Thinking a horn amplifies power like an amplifier; it only transforms impedance and adds no power of its own", "Assuming any short flare works; a mouth that is too small fails to match the air impedance at low frequencies", "Confusing the impedance-transforming action of the horn with simple directivity or beaming control", "Believing the horn changes the driver's electrical impedance directly; it changes the acoustic load on the diaphragm"], "scenario_contexts": ["Selecting a horn profile and mouth size to set low-frequency cutoff and coverage angle", "Using a horn-loaded compression driver to gain sensitivity for a high-output PA system", "Explaining why a bare compression-driver diaphragm radiates poorly without a horn"], "formula_symbolic": "", "formula_words": ""}, {"id": "e13782f8-dff1-4a12-bc8b-2fd6f7e89451", "term": "Impedance Matching", "definition": "Setting a source's and load's impedances to a specified relationship so energy transfers as intended; classic matching makes the load impedance equal (or the complex conjugate) to the source impedance for maximum power transfer. The same idea applies in acoustics and transducers, where a device couples two media or stages, such as a diaphragm to air through a horn, so energy passes efficiently instead of reflecting.", "plain_english": "Impedance is how much a device resists a signal's flow. Matching means setting two connected impedances to work well together. Making them equal delivers the most power, like gears meshing to transfer effort. In acoustics, a horn matches a speaker to the air. In modern audio wiring, gear instead sends a low output into a high input.", "purpose_function": "It makes energy pass efficiently between a source and a load: maximum power when the impedances are equal, or maximum voltage when the load impedance is much higher. It exists so signals transfer with the least loss or reflection for the job at hand.", "practical_application": "A technician matches a 70-volt distributed-line loudspeaker's transformer tap to the amplifier's rating, and separately confirms a mixer's low output feeds a high-impedance input (bridging) for clean line-level transfer.", "category": "Impedance", "difficulty": "intermediate", "achievement_id": "f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37", "cross": [], "related_terms": ["Impedance Bridging", "Radiation Impedance", "Acoustic Transformer", "Maximum Power Transfer", "Output Impedance", "Load Impedance"], "common_mistakes": ["Thinking modern line-level gear should be impedance-matched (equal impedance); it actually uses bridging, a high load impedance, for maximum voltage", "Confusing impedance matching (equal impedance, maximum power) with bridging (load much greater than source, maximum voltage)", "UNSAFE: Connecting a loudspeaker load below the amplifier's rated minimum impedance, which can overheat and damage the amplifier", "Assuming matching always sounds best; the wrong load can overload a source and add loss or distortion"], "scenario_contexts": ["Matching transformer taps on a 70-volt or 100-volt constant-voltage loudspeaker line to the amplifier", "Coupling a loudspeaker diaphragm to the air with a horn (acoustic impedance matching)", "Verifying a source's low output impedance drives a high-impedance input for line-level bridging", "Terminating video or RF cabling at its characteristic impedance to prevent reflections"], "formula_symbolic": "", "formula_words": ""}, {"id": "b225efcf-a52d-43c1-8324-9f7b21a000d4", "term": "Radiation Impedance", "definition": "The complex acoustic (or mechanical) impedance that the surrounding medium presents to a vibrating surface, equal to the sound-pressure reaction divided by the surface's velocity. Its real part, the radiation resistance, accounts for the power actually radiated as sound; its imaginary part, the radiation reactance, represents a co-vibrating added mass of air loading the surface, and both vary strongly with frequency and radiator size.", "plain_english": "When a speaker cone moves, the air pushes back on it. Radiation impedance measures that push-back from the air. Part of it carries sound energy out into the room. The other part is nearby air that rides along and adds weight to the cone. This push-back is weak at low frequencies, so small speakers make bass poorly.", "purpose_function": "It quantifies how well a vibrating surface couples to the air, splitting the load into radiated power (resistance) and added air mass (reactance). It exists to predict a source's efficiency and output, and how much the extra air mass shifts its resonance.", "practical_application": "A designer uses radiation impedance to estimate a driver's efficiency and low-frequency limits, and to understand why small radiators need horns or large areas to radiate effectively.", "category": "Acoustic Impedance", "difficulty": "intermediate", "achievement_id": "f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37", "cross": [], "related_terms": ["Acoustic Impedance", "Acoustic Mass", "Acoustic Transformer", "Impedance Matching", "Radiation Resistance", "Baffle"], "common_mistakes": ["Treating radiation impedance as purely resistive; at low frequencies it is mostly reactive (added air mass), so little sound radiates", "Confusing radiation resistance (the real part, radiated power) with radiation reactance (the imaginary part, mass loading)", "Ignoring that radiation impedance changes with frequency and radiator size", "Forgetting that the added co-vibrating air mass lowers the driver's resonance frequency"], "scenario_contexts": ["Explaining why a small unbaffled driver is an inefficient low-frequency radiator", "Accounting for co-vibrating air mass when predicting a diaphragm's resonance", "Justifying horn loading to raise radiation resistance and efficiency at the throat"], "formula_symbolic": "", "formula_words": ""}, {"id": "0f04e3f2-a687-4507-87f6-f08c0859dc28", "term": "Airborne Wave", "definition": "An airborne wave is a sound wave that travels through air, or another gas, as a longitudinal pressure fluctuation, in which the medium's particles oscillate back and forth along the direction of travel. It is distinguished from structure-borne sound, which propagates as vibration through solid materials.", "plain_english": "An airborne wave is sound moving through the air. The air makes tiny pressure changes as it pushes and pulls. Your ears and microphones sense these changes. It differs from sound that travels through walls or floors.", "purpose_function": "Airborne waves are how most sound reaches listeners and microphones, so understanding them lets engineers predict how sound spreads, reflects, and leaks between spaces.", "practical_application": "A technician controls airborne sound with absorption, barriers, and sealing, for example closing gaps in a wall so speech does not pass between two studios.", "category": "Wave propagation", "difficulty": "intermediate", "achievement_id": "595c0857-5afa-4b6a-a0bb-fdea84ae2a8c", "cross": [], "related_terms": ["Structure-Borne Wave", "Traveling Wave", "Geometric Spreading", "Reflection Coefficient", "Superposition Principle"], "common_mistakes": ["Confusing airborne sound with structure-borne sound; the two need different control methods.", "Assuming a heavy wall alone stops airborne sound, when small air gaps still let it leak through.", "Thinking airborne waves are transverse; in air they are longitudinal pressure waves."], "scenario_contexts": ["Isolating a vocal booth so airborne speech does not bleed into an adjacent live room.", "Diagnosing why voices carry between two rooms through a shared ceiling space.", "Placing a microphone to capture airborne sound from an instrument in a studio."], "formula_symbolic": "", "formula_words": ""}, {"id": "58c227da-3e25-4152-8954-3f980e3df262", "term": "Bending Wave", "definition": "A bending wave is a type of structure-borne wave in a plate, panel, or beam in which the material flexes transversely to its surface as the wave passes. It is dispersive, so its propagation speed rises with frequency, and it depends on the material's bending stiffness and mass per unit area.", "plain_english": "A bending wave is a ripple that flexes a panel up and down as it moves. Picture a wave running along a shaken sheet of metal. Higher pitches travel faster than lower ones. These waves make walls and panels give off sound.", "purpose_function": "Bending waves explain how vibrating panels and walls radiate sound into the air, which matters for both noise control and for panel-radiating loudspeakers.", "practical_application": "A technician considers bending waves when a thin wall or floor re-radiates a neighbor's noise, or when using flat-panel (distributed-mode) loudspeakers.", "category": "Wave propagation", "difficulty": "intermediate", "achievement_id": "595c0857-5afa-4b6a-a0bb-fdea84ae2a8c", "cross": [], "related_terms": ["Flexural Wave", "Structure-Borne Wave", "Airborne Wave", "Phase Velocity", "Group Velocity"], "common_mistakes": ["Treating bending waves as non-dispersive; their speed changes with frequency.", "Confusing bending waves with longitudinal waves in the same material.", "Assuming a stiffer panel always radiates less, when its coincidence behavior simply shifts."], "scenario_contexts": ["Explaining why a lightweight partition re-radiates low-frequency noise into a control room.", "Understanding how a distributed-mode flat-panel loudspeaker produces sound.", "Adding damping to a resonant panel to reduce the sound its bending waves radiate."], "formula_symbolic": "", "formula_words": ""}, {"id": "513ac992-327d-4c6e-a2d7-455b2c9771a6", "term": "Cylindrical Wave", "definition": "A cylindrical wave is a wave whose wavefronts form coaxial cylinders expanding outward from a line source. Because a fixed energy spreads over a growing cylindrical surface, sound pressure amplitude falls in proportion to one over the square root of distance, giving about a 3 dB drop in sound pressure level per doubling of distance.", "plain_english": "A cylindrical wave spreads out from a line, like ripples from a long rod dropped in water. It grows in a tube shape, not a ball. Because it spreads more slowly, it loses about 3 decibels each time the distance doubles. Line-array speakers try to make this pattern.", "purpose_function": "The cylindrical model describes how a line source loses level more slowly with distance than a point source, which helps engineers cover deep audiences evenly.", "practical_application": "A live-sound engineer relies on near-cylindrical spreading from a line array to keep front-to-back level differences small in a large venue.", "category": "Wave propagation", "difficulty": "intermediate", "achievement_id": "595c0857-5afa-4b6a-a0bb-fdea84ae2a8c", "cross": [], "related_terms": ["Geometric Spreading", "Huygens-Fresnel Principle", "Airborne Wave", "Traveling Wave", "Wave Mechanics"], "common_mistakes": ["Using the 6 dB-per-doubling point-source rule for a true line source.", "Assuming any stack of speakers gives cylindrical spreading, when it needs proper coupling and length.", "Forgetting that cylindrical behavior only holds within a limited distance and frequency range."], "scenario_contexts": ["Predicting coverage from a line array in a long concert hall.", "Explaining why a line array is louder at the back than a single point-source box.", "Choosing array length so cylindrical spreading holds across the seating area."], "formula_symbolic": "", "formula_words": ""}, {"id": "e7b53a09-89ef-4259-bfae-210aa860999e", "term": "Flexural Wave", "definition": "A flexural wave is a bending wave in a solid beam, plate, or shell in which the material displaces perpendicular to its surface. It is dispersive, meaning its propagation speed rises with frequency, and it governs much of the sound radiated by vibrating structures.", "plain_english": "A flexural wave bends a solid panel or beam up and down as it travels. It is the same idea as a bending wave. Higher frequencies move faster than lower ones. These waves let vibrating surfaces send sound into a room.", "purpose_function": "Flexural waves determine how structures vibrate and radiate noise, and they set the coincidence frequency where a panel leaks airborne sound most easily.", "practical_application": "A technician accounts for flexural waves when treating a resonant stage deck, floor, or wall that transmits vibration and re-radiates it as audible sound.", "category": "Wave propagation", "difficulty": "intermediate", "achievement_id": "595c0857-5afa-4b6a-a0bb-fdea84ae2a8c", "cross": [], "related_terms": ["Bending Wave", "Structure-Borne Wave", "Group Velocity", "Phase Velocity", "Airborne Wave"], "common_mistakes": ["Treating 'flexural' and 'bending' waves as different things; they name the same wave.", "Assuming flexural waves travel at one fixed speed, when they are dispersive.", "Ignoring flexural resonance when a panel colors or amplifies certain notes."], "scenario_contexts": ["Analyzing why a wooden riser rings at certain frequencies.", "Adding constrained-layer damping to a panel to reduce flexural vibration.", "Understanding the coincidence dip in a wall's sound-insulation curve."], "formula_symbolic": "", "formula_words": ""}, {"id": "a937592c-cd88-4945-badf-8904cbb8ab40", "term": "Fresnel Zone", "definition": "A Fresnel zone is one of a series of concentric ellipsoidal regions surrounding the straight line between a transmitter and receiver, defined by the extra path length a wave travels by way of that region. The first Fresnel zone contains all indirect paths that are longer than the direct path by up to half a wavelength; obstacles intruding into it cause diffraction and signal loss.", "plain_english": "A Fresnel zone is a stretched, football-shaped space around the straight path between a sender and a receiver. Waves passing through it can add to or subtract from the signal. If an object blocks this zone, the signal can weaken. Wireless links try to keep this zone clear.", "purpose_function": "The Fresnel zone concept predicts how obstacles near the line of sight weaken a radio or acoustic link, which guides antenna height and clearance.", "practical_application": "A wireless technician mounts antennas high enough to keep the first Fresnel zone clear of people, walls, and staging for a reliable microphone link.", "category": "Wave propagation", "difficulty": "intermediate", "achievement_id": "595c0857-5afa-4b6a-a0bb-fdea84ae2a8c", "cross": [], "related_terms": ["Huygens-Fresnel Principle", "Wave Number", "Geometric Spreading", "Airborne Wave", "Superposition Principle"], "common_mistakes": ["Thinking a clear line of sight alone is enough, when the Fresnel zone must also be clear.", "Picturing the zone as a thin line rather than a wide ellipsoid.", "Ignoring that lower frequencies need a wider clearance zone."], "scenario_contexts": ["Positioning wireless microphone antennas above a crowd to avoid body blockage.", "Planning a point-to-point radio link across a venue without obstruction.", "Diagnosing dropouts caused by staging intruding into the signal path."], "formula_symbolic": "", "formula_words": ""}, {"id": "b76c1c41-6227-441f-ae53-b1638048bbac", "term": "Geometric Spreading", "definition": "Geometric spreading, also called divergence or spreading loss, is the reduction in wave amplitude and intensity that occurs as a fixed amount of wave energy spreads over an expanding wavefront area. For a point source radiating spherically, intensity falls with the inverse square of distance, giving about a 6 dB drop in sound pressure level per doubling of distance.", "plain_english": "Geometric spreading is how sound gets quieter as it spreads out. The same energy has to cover a bigger area farther away. From a small source, the level drops about 6 decibels each time the distance doubles. It is a loss of level, not a loss of total energy.", "purpose_function": "Geometric spreading explains the basic distance falloff of sound, letting engineers estimate levels and coverage before accounting for absorption or reflections.", "practical_application": "A technician uses the 6 dB-per-doubling rule to estimate level lost from the stage to the back row, then sets gain and adds delay fills.", "category": "Wave propagation", "difficulty": "intermediate", "achievement_id": "595c0857-5afa-4b6a-a0bb-fdea84ae2a8c", "cross": [], "related_terms": ["Cylindrical Wave", "Airborne Wave", "Reflection Coefficient", "Huygens-Fresnel Principle", "Wave Mechanics"], "common_mistakes": ["Applying the 6 dB point-source rule to a line source, which loses only about 3 dB.", "Confusing spreading loss with absorption; spreading does not turn sound into heat.", "Forgetting that spreading estimates assume a free field with no reflections."], "scenario_contexts": ["Estimating stage-to-audience level loss when setting overall system gain.", "Explaining why moving a microphone twice as far drops level by about 6 dB.", "Choosing delay-speaker spacing to offset spreading loss down a long room."], "formula_symbolic": "", "formula_words": ""}, {"id": "3feeef14-3603-4478-bc8e-370e46d31539", "term": "Group Velocity", "definition": "Group velocity is the speed at which the overall envelope, or energy, of a wave packet travels through a medium, equal to the derivative of angular frequency with respect to wave number. In a dispersive medium it can differ from the phase velocity of the individual wave crests.", "plain_english": "Group velocity is the speed of a whole group of waves moving together. Picture a cluster of ripples traveling as a pack. This pack carries the wave's energy and its signal. It can move at a different speed than a single crest inside it.", "purpose_function": "Group velocity describes how fast a signal or energy actually travels, which matters wherever waves of different frequencies spread out at different speeds.", "practical_application": "A technician meets group velocity in dispersive systems such as bending waves in panels or waves in ducts, where different frequencies arrive at different times.", "category": "Wave propagation", "difficulty": "intermediate", "achievement_id": "595c0857-5afa-4b6a-a0bb-fdea84ae2a8c", "cross": [], "related_terms": ["Phase Velocity", "Bending Wave", "Flexural Wave", "Wave Number", "Wave Mechanics"], "common_mistakes": ["Assuming group and phase velocity are always equal; they differ in dispersive media.", "Thinking group velocity describes one crest rather than the whole wave packet.", "Confusing the speed that energy travels with the speed of individual wave crests."], "scenario_contexts": ["Explaining why different frequencies in a panel arrive at slightly different times.", "Understanding signal spreading in a dispersive waveguide or air duct.", "Distinguishing energy travel speed from crest speed in a physics lesson."], "formula_symbolic": "", "formula_words": ""}, {"id": "d5176748-5095-4631-adf9-24bd4a72ddbc", "term": "Huygens-Fresnel Principle", "definition": "The Huygens-Fresnel principle states that every point on a wavefront acts as a source of secondary spherical wavelets, and the new wavefront at a later time is the envelope, or coherent sum, of those wavelets. It explains wave propagation, reflection, refraction, and especially diffraction and interference.", "plain_english": "This principle says every point on a wave acts like a tiny new source. Each point sends out its own little wave. Adding all these little waves together builds the next wavefront. It explains how sound bends around edges and spreads out.", "purpose_function": "The principle gives a way to predict how wavefronts advance and how sound diffracts around obstacles and through openings, which underpins array and coverage design.", "practical_application": "A technician uses this idea to understand how a line array's many small sources sum into one shaped wavefront, and how sound bends around barriers.", "category": "Wave theory", "difficulty": "intermediate", "achievement_id": "595c0857-5afa-4b6a-a0bb-fdea84ae2a8c", "cross": [], "related_terms": ["Fresnel Zone", "Superposition Principle", "Cylindrical Wave", "Geometric Spreading", "Wave Mechanics"], "common_mistakes": ["Forgetting that the wavelets combine coherently, with phase, not just add loudness.", "Thinking only the wavefront's edge points act as sources, when every point does.", "Assuming the wavelets radiate equally in every direction, including backward; the envelope (obliquity) construction is what keeps the wave moving forward."], "scenario_contexts": ["Explaining how sound diffracts around the edge of a stage barrier.", "Understanding how many small drivers form one shaped line-array wavefront.", "Teaching why sound spreads through a doorway as if from a new source."], "formula_symbolic": "", "formula_words": ""}, {"id": "e62541b6-ae8f-4d0f-a42a-23503e832bed", "term": "Modal Density", "definition": "Modal density is the number of acoustic resonant modes present per unit of frequency, expressed in modes per hertz, in a room or enclosure. It increases with frequency, so low frequencies have sparse, widely spaced modes while high frequencies have many densely packed modes.", "plain_english": "Modal density is how many room resonances fall within a frequency range. Low notes have only a few, spread far apart. High notes have so many they blur together. This is why small rooms are hardest to fix in the bass.", "purpose_function": "Modal density explains why bass response in small rooms is uneven, since below a certain frequency sparse modes cause strong peaks and dips that change with position.", "practical_application": "A technician uses modal density, and the related Schroeder frequency, to decide where modal treatment like bass traps helps versus where diffusion and broadband absorption matter.", "category": "Room acoustics", "difficulty": "intermediate", "achievement_id": "595c0857-5afa-4b6a-a0bb-fdea84ae2a8c", "cross": [], "related_terms": ["Standing-Wave Ratio", "Resonance Bandwidth", "Pressure Antinode", "Pressure Node", "Superposition Principle"], "common_mistakes": ["Thinking more modes are always worse, when high modal density actually smooths response.", "Ignoring that small rooms have low modal density in the bass, causing big peaks and dips.", "Confusing modal density with the loudness or strength of any single mode."], "scenario_contexts": ["Explaining why a small control room has uneven bass at the mix position.", "Estimating the frequency above which a room starts to behave diffusely.", "Planning bass trapping for widely spaced low-frequency room modes."], "formula_symbolic": "", "formula_words": ""}, {"id": "988ac85e-6fcf-4c5c-b2bc-d77e24624bc8", "term": "Phase Tracking", "definition": "In sound system optimization, phase tracking describes how closely the phase-versus-frequency responses of two signals or sources follow one another across a frequency range. When two sources' phase responses track, meaning they run parallel and matched, they hold a stable phase relationship and sum coherently, especially through a crossover or overlap region.", "plain_english": "Phase tracking means two signals' timing stays matched across the frequency range. When their phase curves line up, the sounds add together cleanly. When they drift apart, the sounds can partly cancel. Engineers check this when combining speakers.", "purpose_function": "Phase tracking tells an engineer whether two combining sources will add smoothly or cancel, since matched phase over frequency is needed for clean summation at a crossover.", "practical_application": "Using a dual-channel measurement system, a technician compares the phase traces of two speakers and adjusts delay or filters until they track through the crossover.", "category": "System optimization", "difficulty": "intermediate", "achievement_id": "595c0857-5afa-4b6a-a0bb-fdea84ae2a8c", "cross": [], "related_terms": ["Phase Velocity", "Superposition Principle", "Group Velocity", "Huygens-Fresnel Principle", "Standing-Wave Ratio"], "common_mistakes": ["Aligning phase at only one frequency instead of tracking it across the crossover.", "Assuming matched arrival time guarantees matched phase across all frequencies.", "Confusing polarity, a fixed flip, with phase, which changes with frequency."], "scenario_contexts": ["Time-aligning a subwoofer to the main speakers through their crossover region.", "Comparing two loudspeaker models' phase traces before combining them.", "Diagnosing a hollow, thin sound caused by phase misalignment between sources."], "formula_symbolic": "", "formula_words": ""}, {"id": "b634086a-f06b-48fb-b14f-7623476bc539", "term": "Phase Velocity", "definition": "Phase velocity is the speed at which a point of constant phase, such as a single wave crest, travels through a medium, equal to the wavelength times the frequency, or angular frequency divided by wave number. In a dispersive medium it varies with frequency and can differ from the group velocity that carries the wave's energy.", "plain_english": "Phase velocity is the speed of a single wave crest. It is how fast one ridge of the wave moves along. In open air, all sound crests move at the same speed. In some materials, crests of different pitches move at different speeds.", "purpose_function": "Phase velocity defines how fast wave crests move and, together with frequency, sets the wavelength, which is basic to predicting interference and standing waves.", "practical_application": "A technician uses phase velocity, the speed of sound, with frequency to find wavelength when placing microphones, spacing speakers, or predicting comb filtering.", "category": "Wave propagation", "difficulty": "intermediate", "achievement_id": "595c0857-5afa-4b6a-a0bb-fdea84ae2a8c", "cross": [], "related_terms": ["Group Velocity", "Wave Number", "Phase Tracking", "Bending Wave", "Wave Mechanics"], "common_mistakes": ["Assuming phase velocity always equals the speed that energy or a signal travels.", "Forgetting that in dispersive media phase velocity changes with frequency.", "Mixing up wavelength times frequency with wavelength divided by frequency."], "scenario_contexts": ["Calculating wavelength from the speed of sound to space microphones.", "Explaining comb filtering from two arrivals separated by a fixed distance.", "Comparing crest speed and energy speed for waves in a stiff panel."], "formula_symbolic": "", "formula_words": ""}, {"id": "8d5946b9-2939-41af-91c1-51c768d75e86", "term": "Pressure Antinode", "definition": "A pressure antinode is a location in a standing sound wave where the acoustic pressure fluctuation reaches its maximum amplitude, while the air particle velocity is at its minimum. In a room or tube, pressure antinodes occur at rigid boundaries and at points spaced half a wavelength apart along the standing wave.", "plain_english": "A pressure antinode is a spot where a standing sound wave squeezes the air the most. Pressure swings are largest there, but the air barely moves. These spots sit against hard walls. Bass usually sounds loudest at these places.", "purpose_function": "Pressure antinodes mark where sound pressure is greatest in standing waves and room modes, which explains why bass level changes with position and where traps and mics respond most.", "practical_application": "A technician expects strong bass at room corners and walls, which are pressure antinodes, and places subwoofers or bass traps accordingly.", "category": "Room acoustics", "difficulty": "intermediate", "achievement_id": "595c0857-5afa-4b6a-a0bb-fdea84ae2a8c", "cross": [], "related_terms": ["Pressure Node", "Velocity Antinode", "Velocity Node", "Standing-Wave Ratio", "Modal Density"], "common_mistakes": ["Confusing a pressure antinode, maximum pressure, with a velocity antinode, maximum air motion.", "Assuming the room center is a pressure antinode; rigid boundaries usually are.", "Thinking a pressure microphone reads low at an antinode, when it actually reads high."], "scenario_contexts": ["Placing a subwoofer in a corner to couple with pressure antinodes for more output.", "Positioning bass traps where standing-wave pressure peaks.", "Explaining why bass is loud at the wall but weak in the middle of the room."], "formula_symbolic": "", "formula_words": ""}, {"id": "ff506b49-9846-45f1-8db5-9d25beb97b08", "term": "Pressure Node", "definition": "A pressure node is a fixed location in a standing sound wave where the acoustic (sound) pressure amplitude stays essentially zero, holding at the ambient level while pressure fluctuates elsewhere. It coincides with a displacement/velocity antinode, where air particles move most, and forms at an open tube end or open boundary.", "plain_english": "Sound is tiny changes in air pressure. In a standing wave, some spots never change pressure. These spots are pressure nodes. The air still moves a lot there, but the squeeze and stretch cancel out. Open ends of a pipe create a pressure node.", "purpose_function": "It marks where the pressure part of a standing wave cancels, which helps explain how pipes, ports, and rooms resonate and where pressure-sensing microphones read weakest.", "practical_application": "A subwoofer or measurement mic placed at a room mode's pressure node barely excites or captures that mode, so technicians move them toward boundaries, where pressure is strongest.", "category": "Standing Waves", "difficulty": "intermediate", "achievement_id": "595c0857-5afa-4b6a-a0bb-fdea84ae2a8c", "cross": [], "related_terms": ["Pressure Antinode", "Velocity Antinode", "Velocity Node", "Standing Wave", "Traveling Wave"], "common_mistakes": ["Confusing a pressure node (minimum pressure) with a velocity node (minimum motion); they are opposite", "Assuming closed, rigid ends make pressure nodes (they make pressure antinodes)", "Forgetting that nodes and antinodes alternate every quarter wavelength"], "scenario_contexts": ["Locating weak spots for a room mode before placing a subwoofer", "Understanding why an open pipe end resonates at a pressure minimum", "Explaining low mic pickup of a specific low-frequency mode at a certain position"], "formula_symbolic": "", "formula_words": ""}, {"id": "b20c5199-0d6e-4ae6-94ad-68428601ee4e", "term": "Reflection Coefficient", "definition": "The reflection coefficient is the ratio of a reflected wave's pressure amplitude to the incident wave's amplitude at a boundary between two media. For normal incidence it equals (Z2 - Z1)/(Z2 + Z1) in terms of acoustic impedances Z; its magnitude runs from 0 (no reflection) to 1 (total reflection), and the fraction of sound power reflected equals its magnitude squared.", "plain_english": "When sound hits a surface, part of it bounces back. The reflection coefficient tells you how much bounces back. Zero means nothing reflects. One means it all bounces off, like from a hard wall. It depends on how different the two materials are.", "purpose_function": "It quantifies how strongly a boundary reflects sound, which sets absorption (absorbed power equals one minus reflected power) and predicts echoes and reverberation.", "practical_application": "Acousticians read reflection coefficients from impedance-tube tests to pick wall treatments; a low reflection coefficient means the material absorbs well and tames reflections.", "category": "Wave Reflection", "difficulty": "intermediate", "achievement_id": "595c0857-5afa-4b6a-a0bb-fdea84ae2a8c", "cross": [], "related_terms": ["Transmission Coefficient", "Standing-Wave Ratio", "Absorption Coefficient", "Acoustic Impedance", "Traveling Wave"], "common_mistakes": ["Confusing the amplitude reflection coefficient (which can be negative) with the reflected power fraction (its square)", "Assuming the magnitude can exceed 1", "Ignoring the phase flip when sound reflects off a harder (higher-impedance) medium"], "scenario_contexts": ["Choosing absorptive panels rated by their measured reflection", "Predicting flutter echo between two hard parallel walls", "Explaining why a large impedance mismatch causes strong reflections"], "formula_symbolic": "", "formula_words": ""}, {"id": "45788cd1-6ae5-466a-ae2f-7369d2dd95fd", "term": "Resonance Bandwidth", "definition": "Resonance bandwidth is the width of a resonance peak measured between its two half-power (-3 dB) points, one on each side of the resonant frequency. It ties to the quality factor by Q = resonant frequency / bandwidth, so a narrow bandwidth means a sharp, high-Q, lightly damped resonance.", "plain_english": "A resonance is a frequency where a system rings loudly. It also responds to nearby frequencies a little. Bandwidth is the width of that range. A narrow bandwidth means a sharp, ringing peak. A wide bandwidth means a broad, well-damped one.", "purpose_function": "It measures how sharp or damped a resonance is, letting engineers predict ringing, decay, and how selective a room mode, filter, or driver is.", "practical_application": "When ringing out a room or setting an EQ notch, a technician matches the filter's bandwidth (Q) to the resonance's bandwidth to cancel it without disturbing nearby frequencies.", "category": "Resonance", "difficulty": "intermediate", "achievement_id": "595c0857-5afa-4b6a-a0bb-fdea84ae2a8c", "cross": [], "related_terms": ["Resonance", "Standing Wave", "Room Mode", "Damping", "Modal Density"], "common_mistakes": ["Confusing bandwidth with the center (resonant) frequency", "Assuming high Q is always desirable; it also means longer ringing and decay", "Measuring peak width at the wrong reference instead of the -3 dB half-power points"], "scenario_contexts": ["Setting a parametric EQ notch to tame a room mode", "Comparing how sharply two loudspeaker drivers resonate", "Estimating how long a lightly damped mode will ring"], "formula_symbolic": "", "formula_words": ""}, {"id": "74c927bb-8c60-4c1c-a67f-5d121d74f181", "term": "Standing-Wave Ratio", "definition": "The standing-wave ratio (SWR) is the ratio of the maximum pressure amplitude to the minimum pressure amplitude along a standing-wave pattern formed by an incident wave and its reflection. It relates to the reflection coefficient by SWR = (1 + |R|)/(1 - |R|), running from 1 (no reflection, a pure traveling wave) up toward infinity (total reflection), and it is measured in impedance tubes to find sound absorption.", "plain_english": "When a wave reflects, the outgoing and returning waves overlap. They make loud and quiet spots that stay in place. The standing-wave ratio compares the loudest spot to the quietest. A value of one means no reflection. A big value means strong reflection.", "purpose_function": "It gives one number for how much of a wave reflects versus passes or is absorbed, used to test materials and spot impedance mismatches.", "practical_application": "In an impedance tube, a technician slides a probe to find the pressure maximum and minimum, computes the standing-wave ratio, and derives a material's absorption coefficient.", "category": "Wave Reflection", "difficulty": "intermediate", "achievement_id": "595c0857-5afa-4b6a-a0bb-fdea84ae2a8c", "cross": [], "related_terms": ["Reflection Coefficient", "Absorption Coefficient", "Standing Wave", "Acoustic Impedance", "Traveling Wave"], "common_mistakes": ["Thinking a standing-wave ratio of 1 means total reflection; it actually means none", "Reading only the maximum without the minimum", "Assuming acoustic SWR differs mathematically from RF/antenna VSWR; the relationship is the same"], "scenario_contexts": ["Measuring a sample's absorption in an impedance tube", "Judging how reflective a boundary is from a single ratio", "Relating acoustic SWR to the familiar antenna VSWR concept"], "formula_symbolic": "", "formula_words": ""}, {"id": "d3a32886-f19e-4565-9149-3aeaa59444a9", "term": "Structure-Borne Wave", "definition": "A structure-borne wave is vibrational energy that travels through and within solid structures such as floors, walls, beams, and equipment mounts, rather than through the air. Injected by impacts, machinery, or footfall, it propagates as compressional, shear, or bending waves and can radiate audible airborne sound wherever a structural surface vibrates.", "plain_english": "Sound can travel through solid things, not just air. Footsteps, motors, and knocks push vibrations into floors and walls. Those vibrations spread through the building. When a surface shakes, it makes sound in the next room. That is structure-borne sound.", "purpose_function": "The idea explains how noise passes between rooms through the building itself, guiding isolation design that airborne treatment alone cannot fix.", "practical_application": "To stop structure-borne noise, technicians decouple sources with isolation mounts, floating floors, or resilient pads, breaking the vibration path from a subwoofer, HVAC unit, or footfall.", "category": "Sound Transmission", "difficulty": "intermediate", "achievement_id": "595c0857-5afa-4b6a-a0bb-fdea84ae2a8c", "cross": [], "related_terms": ["Airborne Wave", "Bending Wave", "Flexural Wave", "Transmission Coefficient", "Traveling Wave"], "common_mistakes": ["Treating structure-borne noise with foam or absorption meant for airborne sound", "Rigidly bolting gear to the structure, which transmits vibration instead of blocking it", "Confusing the airborne path (through air) with the structure-borne path (through solids)"], "scenario_contexts": ["Isolating a subwoofer or drum riser from the floor", "Reducing footfall noise between a studio and the room below", "Mounting HVAC or motors on vibration isolators to cut transmitted noise"], "formula_symbolic": "", "formula_words": ""}, {"id": "df3f015f-7045-4fa3-ad33-c4324051e86f", "term": "Superposition Principle", "definition": "The superposition principle states that when two or more waves overlap in the same medium, the resultant disturbance at each point equals the algebraic sum of the individual waves' disturbances. It holds in linear media and underlies interference, standing waves, and beats; after overlapping, each wave continues unchanged.", "plain_english": "When waves meet, they add together. At each point you just add their ups and downs. Two crests together make a bigger crest. A crest meeting a trough can cancel out. After they pass, each wave keeps going as before.", "purpose_function": "It is the basic rule that lets engineers predict interference, standing waves, comb filtering, and how multiple sound sources combine in a space.", "practical_application": "A technician uses superposition to see why two speakers add up when in phase but cancel when out of phase, causing comb filtering and dead spots where their signals overlap.", "category": "Wave Mechanics", "difficulty": "intermediate", "achievement_id": "595c0857-5afa-4b6a-a0bb-fdea84ae2a8c", "cross": [], "related_terms": ["Traveling Wave", "Standing-Wave Ratio", "Pressure Node", "Phase Tracking", "Wave Mechanics"], "common_mistakes": ["Assuming amplitudes always add; they add algebraically and can cancel", "Adding sound levels in decibels directly instead of combining pressures", "Expecting perfect superposition at very high levels, where the medium behaves nonlinearly"], "scenario_contexts": ["Explaining comb filtering when two mics or speakers overlap", "Predicting nulls and peaks from two arriving signals", "Understanding how a standing wave forms from two opposing traveling waves"], "formula_symbolic": "", "formula_words": ""}, {"id": "427026db-f8bb-4ae2-9561-7781d24320e2", "term": "Transmission Coefficient", "definition": "The transmission coefficient describes how much of an incident wave crosses a boundary into the second medium. As a pressure ratio at normal incidence it equals 2Z2/(Z2 + Z1) and satisfies 1 + R = T with the reflection coefficient; as an intensity/power ratio it is the fraction of incident sound power transmitted (one minus the intensity reflection coefficient), and sound transmission loss equals ten times the base-10 logarithm of its reciprocal.", "plain_english": "When sound hits a wall or boundary, part of it passes through. The transmission coefficient tells you how much gets through. A small value means the barrier blocks most sound. A large value means sound passes easily. It depends on the two materials that meet.", "purpose_function": "It quantifies how much sound energy crosses a partition, forming the basis of sound-isolation ratings and transmission loss.", "practical_application": "When rating a wall or door, technicians work from the power transmission coefficient to compute transmission loss and pick partitions that meet isolation targets between rooms.", "category": "Wave Transmission", "difficulty": "intermediate", "achievement_id": "595c0857-5afa-4b6a-a0bb-fdea84ae2a8c", "cross": [], "related_terms": ["Reflection Coefficient", "Structure-Borne Wave", "Airborne Wave", "Acoustic Impedance", "Standing-Wave Ratio"], "common_mistakes": ["Confusing the pressure transmission coefficient (which can exceed 1) with the power/intensity fraction (0 to 1)", "Assuming reflection plus transmission amplitudes sum to 1; energy is conserved, not amplitude", "Forgetting that transmission loss is ten log of one over the power transmission coefficient"], "scenario_contexts": ["Estimating how much sound leaks through a studio partition", "Comparing barrier materials by their transmitted energy", "Relating impedance mismatch to how little sound gets through a boundary"], "formula_symbolic": "", "formula_words": ""}, {"id": "508167c1-d917-4d00-99b4-598debc24fc5", "term": "Traveling Wave", "definition": "A traveling (progressive) wave is a disturbance that propagates through a medium at a constant speed, carrying energy from one place to another while the medium's particles only oscillate about their rest positions with no net transport of matter. It contrasts with a standing wave, whose pattern does not move through space.", "plain_english": "A traveling wave moves forward through a material. It carries energy from one place to another. The material itself does not travel with it. Each bit just wiggles in place, like a ripple crossing a pond. The water stays; the wave moves.", "purpose_function": "It describes how sound actually carries energy from a source to a listener, the normal way sound moves before reflections build standing waves.", "practical_application": "Sound leaving a loudspeaker moves as a traveling wave until it meets boundaries; understanding it helps technicians predict arrival times, align delays, and separate direct from reflected sound.", "category": "Wave Propagation", "difficulty": "intermediate", "achievement_id": "595c0857-5afa-4b6a-a0bb-fdea84ae2a8c", "cross": [], "related_terms": ["Standing Wave", "Superposition Principle", "Wave Number", "Geometric Spreading", "Phase Velocity"], "common_mistakes": ["Thinking the air travels along with the wave; only energy does", "Confusing a traveling wave with a standing wave", "Assuming the energy travels without loss, ignoring spreading and absorption"], "scenario_contexts": ["Timing the direct sound arrival from a speaker to a listener", "Distinguishing the outgoing wave from its later reflections", "Explaining why moving air is not required for sound to travel"], "formula_symbolic": "", "formula_words": ""}, {"id": "dd1600c8-60ec-4b6d-ba1c-009af8d613d7", "term": "Velocity Antinode", "definition": "A velocity antinode is a fixed location in a standing sound wave where the particle-velocity (and displacement) amplitude is maximum. It coincides with a pressure node and occurs at an open tube end or open boundary, where the air can move most freely.", "plain_english": "In a standing sound wave, air particles move back and forth. At some spots they move the most. These spots are velocity antinodes. There, the air swings freely but the pressure barely changes. Open ends of a pipe sit at a velocity antinode.", "purpose_function": "It marks where air motion is greatest in a standing wave, key to understanding wind-instrument tone, port tuning, and where velocity-sensing (ribbon) response peaks.", "practical_application": "A technician tuning a bass-reflex port or a resonant tube uses the fact that the open end is a velocity antinode (and pressure node) to predict resonance and airflow noise.", "category": "Standing Waves", "difficulty": "intermediate", "achievement_id": "595c0857-5afa-4b6a-a0bb-fdea84ae2a8c", "cross": [], "related_terms": ["Velocity Node", "Pressure Node", "Pressure Antinode", "Standing Wave", "Traveling Wave"], "common_mistakes": ["Confusing a velocity antinode (maximum motion) with a pressure antinode (maximum pressure); they sit a quarter wavelength apart", "Assuming closed, rigid ends are velocity antinodes; they are velocity nodes", "Thinking pressure is also greatest where velocity is greatest"], "scenario_contexts": ["Predicting resonance at the open end of a tuned port", "Explaining strong air movement and possible port noise at a pipe opening", "Relating open-end behavior to a wind instrument's tone"], "formula_symbolic": "", "formula_words": ""}, {"id": "325da22b-11b9-4e1c-8950-b472773bec05", "term": "Velocity Node", "definition": "A velocity node is a fixed location in a standing sound wave where the particle-velocity (and displacement) amplitude is zero. It coincides with a pressure antinode and occurs at a closed, rigid boundary, where the air cannot move.", "plain_english": "In a standing sound wave, some spots have air that barely moves. These spots are velocity nodes. There, the pressure changes the most instead. A hard, closed wall forces a velocity node, because air cannot pass through it.", "purpose_function": "It marks where air motion stops but pressure swings hardest, explaining behavior at rigid boundaries and where pressure microphones read strongest.", "practical_application": "A boundary or PZM microphone laid flat on a hard wall sits at a velocity node (pressure antinode), so it captures maximum pressure and avoids phase cancellation with reflections.", "category": "Standing Waves", "difficulty": "intermediate", "achievement_id": "595c0857-5afa-4b6a-a0bb-fdea84ae2a8c", "cross": [], "related_terms": ["Velocity Antinode", "Pressure Antinode", "Pressure Node", "Standing Wave", "Acoustic Impedance"], "common_mistakes": ["Confusing a velocity node with a pressure node; they are opposite", "Assuming open tube ends are velocity nodes; they are velocity antinodes", "Ignoring that nodes and antinodes alternate every quarter wavelength"], "scenario_contexts": ["Placing a boundary mic on a wall to capture maximum pressure", "Explaining why a rigid wall forces air motion to zero", "Understanding strong pressure buildup at a closed pipe end"], "formula_symbolic": "", "formula_words": ""}, {"id": "5b2fe559-7e37-4b4c-bbfa-699c096b6966", "term": "Wave Mechanics", "definition": "In acoustics, wave mechanics is the branch of physics describing how waves arise, propagate, and interact, covering reflection, refraction, diffraction, interference, superposition, and resonance. It supplies the mathematical framework, such as wavelength, frequency, wave number, and phase and group velocity, used to predict how sound behaves in air, in solids, and in enclosed spaces.", "plain_english": "Wave mechanics is the study of how waves move and behave. It explains how sound travels, bounces, bends, and adds together. It uses ideas like wavelength, frequency, and speed. These rules let engineers predict what sound will do in a room or a pipe.", "purpose_function": "It gives the shared rules behind all acoustic behavior, letting technicians reason about resonance, reflections, and interference instead of guessing.", "practical_application": "Every acoustic decision, from speaker placement to room treatment to mic technique, rests on wave mechanics, for example predicting where room modes and cancellations will occur.", "category": "Wave Mechanics", "difficulty": "intermediate", "achievement_id": "595c0857-5afa-4b6a-a0bb-fdea84ae2a8c", "cross": [], "related_terms": ["Superposition Principle", "Wave Number", "Traveling Wave", "Standing Wave", "Phase Velocity"], "common_mistakes": ["Confusing the acoustic sense with quantum wave mechanics, a different subject", "Treating sound only as straight rays and ignoring diffraction and interference", "Assuming wave rules stay linear even at very high sound levels"], "scenario_contexts": ["Reasoning about room modes before treating a control room", "Predicting interference and cancellations between sources", "Explaining why low frequencies bend around obstacles"], "formula_symbolic": "", "formula_words": ""}, {"id": "194067f0-73e9-4551-abc7-653e76b301a7", "term": "Wave Number", "definition": "The angular wave number k is the spatial frequency of a wave: the phase in radians per unit distance, equal to 2 pi divided by the wavelength (k = 2 pi / wavelength), with units of radians per meter. It is the spatial counterpart of angular frequency and appears throughout wave equations that relate phase to position.", "plain_english": "Wave number tells you how tightly packed a wave is in space. It counts how much the wave cycles over a set distance. A short wavelength gives a high wave number. A long wavelength gives a low one. It is the space version of frequency.", "purpose_function": "It links a wave's spatial pattern to its phase, letting engineers turn distances into phase shifts and predict path differences and interference.", "practical_application": "A technician computing comb-filter spacing or the phase between two arrival paths uses the wave number to convert a distance into a phase difference at a given frequency.", "category": "Wave Mechanics", "difficulty": "intermediate", "achievement_id": "595c0857-5afa-4b6a-a0bb-fdea84ae2a8c", "cross": [], "related_terms": ["Wavelength", "Phase Velocity", "Traveling Wave", "Wave Mechanics", "Superposition Principle"], "common_mistakes": ["Confusing angular wave number (2 pi over wavelength, radians per meter) with the spectroscopic wave number (one over wavelength, cycles per meter)", "Mixing up wave number with frequency", "Dropping or mislabeling the units"], "scenario_contexts": ["Calculating phase difference from a path-length difference", "Working out comb-filter notch spacing between two sources", "Relating wavelength to spatial phase in a wave equation"], "formula_symbolic": "", "formula_words": ""}, {"id": "cabffd94-6f8e-4ae9-8c40-83c25e18da95", "term": "Lin/Log (Linear vs Logarithmic display/taper)", "definition": "Lin/Log is the choice between a linear scale and a logarithmic scale for a control's taper or a graph's axis. On a linear scale, equal steps represent equal absolute change; on a logarithmic scale, equal steps represent equal ratios (for example, each octave or each 10 dB). Because human hearing responds to ratios of frequency and level rather than absolute differences, audio frequency axes, dB level scales, and volume-control tapers are normally logarithmic. A 'Lin/Log' control switches a meter, analyzer, EQ display, or automation/parameter between the two.", "plain_english": "Lin means a linear scale. Log means a logarithmic scale. On a linear scale, every step adds the same amount. On a log scale, every step multiplies by the same amount. Audio uses log scales for pitch, loudness, and volume knobs because ears hear ratios. A Lin/Log button just switches how a graph or control is spaced.", "purpose_function": "Lets a display or control match how people actually hear. A logarithmic scale spreads the wide audio range — roughly 20 Hz to 20 kHz and a large span of levels — into even, readable steps, so octaves look equally wide and a volume knob feels smooth. A linear scale is used when equal absolute values matter, such as inspecting low-level detail or sample-accurate values.", "practical_application": "Set an RTA, FFT, or EQ frequency axis to Log so each octave takes equal width and broad tonal balance is easy to read; switch to Lin to zoom in on evenly spaced Hz. Choose a log (audio) taper for a volume or fader control so loudness changes sound gradual. Toggle an analyzer's amplitude axis Lin vs Log (or dB) to reveal quiet detail.", "category": "Scales & Metering", "difficulty": "beginner", "achievement_id": "525bdc16-2acc-4b5b-aaa6-781ddb284216", "cross": ["07df90cd-38fa-4737-8b35-b63864c78de1"], "related_terms": ["Linear Scale", "Logarithmic Scale", "Decibel (dB)", "Logarithm", "Octave", "Audio Taper", "Linear-taper potentiometer", "Potentiometer", "Lin", "Log"], "common_mistakes": ["Reading a log frequency axis as if it were linear, and misjudging where a frequency actually sits.", "Using a linear-taper potentiometer for volume — most of the useful change bunches at one end; an audio (log) taper is needed.", "Confusing a Lin/Log display toggle, which only changes the view, with a process that changes the signal."], "scenario_contexts": ["Setting an analyzer or EQ to a Log frequency axis so octaves read at equal width.", "Selecting a log (audio) taper volume control so level changes sound even to the ear.", "Toggling an FFT plot between Lin and Log to inspect low-level detail versus overall balance."], "formula_symbolic": "", "formula_words": ""}]$ap$::jsonb)),
elig AS (SELECT r FROM p
  WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id=(r->>'id')::uuid)
    AND NOT EXISTS (SELECT 1 FROM glossary g WHERE g.term=r->>'term')),
g AS (
  INSERT INTO glossary (id, term, definition, plain_english, purpose_function, practical_application,
     category, difficulty, related_terms, common_mistakes, scenario_contexts, formula_symbolic, formula_words, achievement_id)
  SELECT (r->>'id')::uuid, r->>'term', r->>'definition',
     NULLIF(r->>'plain_english',''), NULLIF(r->>'purpose_function',''), NULLIF(r->>'practical_application',''),
     NULLIF(r->>'category',''), NULLIF(r->>'difficulty',''),
     ARRAY(SELECT jsonb_array_elements_text(r->'related_terms')),
     ARRAY(SELECT jsonb_array_elements_text(r->'common_mistakes')),
     ARRAY(SELECT jsonb_array_elements_text(r->'scenario_contexts')),
     NULLIF(r->>'formula_symbolic',''), NULLIF(r->>'formula_words',''), (r->>'achievement_id')::uuid
  FROM elig ON CONFLICT (id) DO NOTHING RETURNING 1
),
tp AS (
  INSERT INTO glossary_topics (glossary_id, achievement_id, is_primary, difficulty)
  SELECT (r->>'id')::uuid, (r->>'achievement_id')::uuid, true, NULLIF(r->>'difficulty','')
  FROM elig WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id=(r->>'id')::uuid AND gt.achievement_id=(r->>'achievement_id')::uuid)
  RETURNING 1
)
INSERT INTO glossary_topics (glossary_id, achievement_id, is_primary, difficulty)
SELECT (r->>'id')::uuid, ct::uuid, false, NULLIF(r->>'difficulty','')
FROM elig, jsonb_array_elements_text(r->'cross') ct
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id=(r->>'id')::uuid AND gt.achievement_id=ct::uuid);
COMMIT;
